import 'package:flutter/material.dart';
import 'barber_store.dart';

class TeamPage extends StatefulWidget { const TeamPage({super.key}); @override State<TeamPage> createState()=>_TeamPageState(); }
class _TeamPageState extends State<TeamPage>{
 static const _gold=Color(0xFFD7A84B); bool _loading=true,_saving=false; List<BarberRecord> _barbers=const [];
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{setState(()=>_loading=true);try{final barbers=await BarberStore.loadAll();if(!mounted)return;setState((){_barbers=barbers;_loading=false;});}catch(_){if(!mounted)return;setState(()=>_loading=false);_showError('Não foi possível carregar os profissionais.');}}
 Future<String?> _askName({String? initialValue})async{final controller=TextEditingController(text:initialValue??'');final result=await showDialog<String>(context:context,builder:(context)=>AlertDialog(backgroundColor:const Color(0xFF202020),title:Text(initialValue==null?'Cadastrar profissional':'Editar profissional'),content:TextField(controller:controller,autofocus:true,textCapitalization:TextCapitalization.words,decoration:const InputDecoration(labelText:'Nome do profissional',hintText:'Ex.: João'),onSubmitted:(value)=>Navigator.pop(context,value.trim())),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(context,controller.text.trim()),style:FilledButton.styleFrom(backgroundColor:_gold,foregroundColor:Colors.black),child:const Text('Salvar'))]));controller.dispose();final clean=result?.trim();return clean==null||clean.isEmpty?null:clean;}
 Future<void> _addBarber()async{if(_saving)return;final name=await _askName();if(name==null)return;setState(()=>_saving=true);try{await BarberStore.add(name);await _load();if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$name cadastrado com sucesso.')));}on ProfessionalPlanLimitException catch(e){if(mounted)_showError('Limite de profissionais ativos do plano atingido (${e.limit}). Faça upgrade do plano para cadastrar ou ativar mais profissionais.');}catch(_){if(mounted)_showError('Não foi possível cadastrar o profissional.');}finally{if(mounted)setState(()=>_saving=false);}}
 Future<void> _renameBarber(BarberRecord barber)async{if(_saving)return;final name=await _askName(initialValue:barber.name);if(name==null||name==barber.name)return;setState(()=>_saving=true);try{await BarberStore.rename(barber.id,name);await _load();if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Nome atualizado com sucesso.')));}catch(_){if(mounted)_showError('Não foi possível editar o profissional.');}finally{if(mounted)setState(()=>_saving=false);}}
