}
class _ProfessionalCard extends StatelessWidget{const _ProfessionalCard({required this.barber,required this.disabled,required this.onEdit,required this.onActiveChanged});final BarberRecord barber;final bool disabled;final VoidCallback onEdit;final ValueChanged<bool> onActiveChanged;@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFF1D1D1D),borderRadius:BorderRadius.circular(20),border:Border.all(color:barber.active?Colors.white10:Colors.redAccent.withValues(alpha:.3))),child:Row(children:[CircleAvatar(radius:29,backgroundColor:barber.active?const Color(0xFF2B2418):Colors.white10,child:Icon(Icons.person_rounded,color:barber.active?_TeamPageState._gold:Colors.white38,size:32)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(barber.name,style:TextStyle(fontSize:18,fontWeight:FontWeight.w800,color:barber.active?Colors.white:Colors.white54)),const SizedBox(height:4),Text(barber.active?'Ativo para agendamentos':'Desativado',style:TextStyle(color:barber.active?Colors.greenAccent:Colors.redAccent,fontWeight:FontWeight.w700))])),IconButton(tooltip:'Editar nome',onPressed:disabled?null:onEdit,icon:const Icon(Icons.edit_outlined)),Switch(value:barber.active,onChanged:disabled?null:onActiveChanged,activeTrackColor:_TeamPageState._gold)]));}
